import{_ as t,o as e,c as a,a2 as r}from"./chunks/framework.Cvf4Fkn6.js";const p=JSON.parse('{"title":"更新记录","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md","lastUpdated":1794719636000}'),l={name:"changelog.md"};function n(i,o,s,c,d,g){return e(),a("div",null,[...o[0]||(o[0]=[r('<h1 id="更新记录" tabindex="-1">更新记录 <a class="header-anchor" href="#更新记录" aria-label="Permalink to &quot;更新记录&quot;">​</a></h1><p>WTidy 的版本更新记录，新版本在顶部追加。版本号与 GitHub Releases 的 tag 一致。</p><p>下载请前往 <a href="https://github.com/crazy-airhead/WTidy/releases/latest" target="_blank" rel="noreferrer">最新版本</a>。</p><blockquote><p><strong>macOS 未公证提示</strong>：应用为 ad-hoc 签名、未做 Apple 公证，首次打开若提示无法验证开发者，<strong>右键 App →「打开」</strong>，或执行 <code>xattr -d com.apple.quarantine /Applications/WTidy.app</code> 后再打开。</p></blockquote><h2 id="v0-1-2-·-2026-11-15" tabindex="-1">v0.1.2 · 2026-11-15 <a class="header-anchor" href="#v0-1-2-·-2026-11-15" aria-label="Permalink to &quot;v0.1.2 · 2026-11-15&quot;">​</a></h2><ul><li><strong>修复</strong> 拖动窗口偶发呼不出图标条：上一次未成型的轻微拖动不再拖累下一次（此前可能要拖得更远才触发）；前台应用忙碌导致监听瞬时断开时自动重连，无需切换窗口或等待心跳</li></ul><h2 id="v0-1-1-·-2026-11-13" tabindex="-1">v0.1.1 · 2026-11-13 <a class="header-anchor" href="#v0-1-1-·-2026-11-13" aria-label="Permalink to &quot;v0.1.1 · 2026-11-13&quot;">​</a></h2><ul><li><strong>新增</strong> 内置布局自带区域快捷键：8 个内置布局的每个区域都预置了 <code>⌥⌘</code> 加一键的默认组合，在布局列表里可见、可改录、可清除；已有的布局列表升级后自动补上</li><li><strong>优化</strong> 快捷键更短：上下半屏、左 2/3 / 右 1/3、最大化由三修饰键改为 <code>⌥⌘↑/↓</code>、<code>⌥⌘;</code> / <code>⌥⌘&#39;</code>、<code>⌥⌘F</code>；原固定方向快捷键并入内置布局，可自由改录</li><li><strong>修复</strong> 布局列表行尾的清除钮不再贴着或被滚动条遮挡；设置页不再能左右晃动</li><li><strong>移除</strong> 「自动分组相邻互补布局」开关：布局本身已是多区域一体设计，不再需要把相邻布局合并成一个图标</li></ul><h2 id="v0-1-0-·-2026-11-13" tabindex="-1">v0.1.0 · 2026-11-13 <a class="header-anchor" href="#v0-1-0-·-2026-11-13" aria-label="Permalink to &quot;v0.1.0 · 2026-11-13&quot;">​</a></h2><p>首个发布版本。原生重制的 macOS 窗口分屏工具，致敬 Window Tidy（Light Pillar, 2011–2017）。</p><ul><li><strong>拖拽分屏</strong>：拖动窗口标题栏浮现布局图标条，图标内投影瞄准 + 整屏落点预览，松手吸附；其他位置松手不打扰</li><li><strong>布局自定义</strong>：内置 8 种布局；「网格 + 区域」编辑器（如 6×6 网格区域 <code>(2,2)-(5,5)</code> = 居中），实时预览缩略图，作用域支持所有屏幕 / 指定显示器</li><li><strong>菜单栏</strong>：应用布局到前台窗口（迷你预览 + 中心投影选区）、恢复所有窗口位置、发送窗口到另一块屏、最近吸附记录</li><li><strong>吸附动画</strong>：平滑动画；跨屏吸附自动分三阶段（移到目标屏原点 → 调整尺寸 → 移到最终位置），避免大窗口跨屏被裁剪</li><li><strong>自动分组</strong>：相邻同网格互补布局自动合并为单图标，图标内投影选区</li><li><strong>全局快捷键</strong>：方向半屏 / 三分 / 最大化 / 居中等固定组合，另支持每区域自定义录制（行内即录 + 冲突拦截）</li><li><strong>图标条主题</strong>：墨蓝 / 石墨 / 青碧 / 紫罗兰四套配色，背景支持默认深底或桌面壁纸</li><li><strong>可靠性</strong>：看门狗自愈（事件驱动重挂 + 10 秒心跳 + 60 秒重建）、菜单栏双态图标、SMAppService 现代登录项、日志轮转、arm64 原生</li><li><strong>国际化</strong>：简体中文 / English 跟随系统语言</li></ul>',11)])])}const u=t(l,[["render",n]]);export{p as __pageData,u as default};
